import {validateParts,containsPoint} from './contour-geometry.mjs';
import {deriveAsepsis} from './documentary-evidence.mjs';
import {checkpoint,latestCheckpoint} from './persistence.mjs';
import {searchRooms,validatePolygon,inside,intersects} from './engine.mjs';
import {loadRuntime} from './runtime-loader.mjs';
import {nivel,datos,clave,archivo} from './level.mjs';
const KEY=clave('atlas-hpc-web-v1'),MIGRATION=clave('atlas-recovery-migration-v1');let baseline,records,stateCache;
const clone=x=>structuredClone(x);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}');}catch{throw Error('No se pueden leer las correcciones locales. Revisa los permisos de almacenamiento del navegador.');}}
function write(x){try{localStorage.setItem(KEY,JSON.stringify(x));}catch{throw Error('No se pudo guardar en este navegador. Descarga un respaldo antes de continuar.');}}
export async function initializeStore(){if(!baseline){baseline=(await loadRuntime()).data;records=read();if(Object.keys(records).length&&!localStorage.getItem(MIGRATION)){await checkpoint(records,'Migración no destructiva');localStorage.setItem(MIGRATION,'1');}}if(!stateCache){stateCache={...baseline,rooms:baseline.rooms.map(r=>{const value=clone(records[r.id]||r);value.asepsis=deriveAsepsis(value.finishes);return value;})};}return stateCache;}
const geometryPromises=new Map();
export async function ensureDocumentGeometry(id){
  await initializeStore();
  if(!geometryPromises.has(id)) geometryPromises.set(id,(async()=>{
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
    try{const response=await fetch(datos('geometry/'+encodeURIComponent(id)+'.json'),{signal:controller.signal});if(!response.ok)throw Error('No se pudo abrir el contorno técnico. Guarda el plano sin conexión o reintenta.');const payload=await response.json(),byId=new Map(payload.rooms.map(r=>[r.id,r]));for(const r of baseline.rooms)if(byId.has(r.id))Object.assign(r,byId.get(r.id));for(const r of stateCache.rooms)if(byId.has(r.id)&&!records[r.id])Object.assign(r,byId.get(r.id));}
    catch(e){geometryPromises.delete(id);throw e;}finally{clearTimeout(timer);}
  })());
  await geometryPromises.get(id);return stateCache;
}
const vendorPromises=new Map();
export function loadVendor(kind){const file=kind==='pdf'?'pdf-lib.min.js':'xlsx.full.min.js';if(!vendorPromises.has(kind))vendorPromises.set(kind,new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/vendor/'+file;s.onload=resolve;s.onerror=()=>reject(Error('No se pudo cargar la herramienta de exportación.'));document.head.append(s);}));return vendorPromises.get(kind);}
export async function localAPI(url,options){const state=await initializeStore();const u=new URL(url,location.origin);if(u.pathname==='/api/bootstrap')return state;if(u.pathname==='/api/search'){const start=performance.now(),rooms=searchRooms(state.rooms,u.searchParams);return {rooms,count:rooms.length,elapsed_ms:performance.now()-start};}const id=decodeURIComponent(u.pathname.split('/').at(-1)),r=state.rooms.find(r=>r.id===id);if(!r)throw Error('Recinto no encontrado');if(!options||options.method!=='PATCH')return r;await ensureDocumentGeometry(r.document_id);records=read();const current=records[id]||baseline.rooms.find(x=>x.id===id),b=JSON.parse(options.body);if(b.version!==current.version)throw Error('El recinto cambió en otra pestaña. Recarga antes de editar.');if(!b.responsible?.trim()||!b.reason?.trim())throw Error('Indica responsable y motivo.');const next={...clone(current),...b};delete next.responsible;delete next.reason;delete next.review_confirmed;if(!next.code.trim()||!next.name.trim())throw Error('Código y nombre obligatorios');const doc=state.documents.find(d=>d.id===r.document_id);
if(b.geometry_parts!==undefined){if(b.geometry_parts===null){delete next.geometry_parts;}else{validateParts(b.geometry_parts,doc.width,doc.height);if(!containsPoint(b.geometry_parts,current.position))throw Error('El contorno debe contener la etiqueta del recinto de esta fuente.');for(const other of state.rooms)if(other.id!==id&&other.document_id===r.document_id&&containsPoint(b.geometry_parts,other.position))throw Error('El contorno contiene la etiqueta de otro recinto: '+other.code);next.geometry_parts=clone(b.geometry_parts);next.polygon=b.geometry_parts.length===1?clone(b.geometry_parts[0].polygon):null;next.holes=b.geometry_parts.length===1?clone(b.geometry_parts[0].holes):[];next.has_polygon=true;next.geometry_method='Edición manual en navegador';next.geometry_status='Pendiente de revisión';next.status='Pendiente de revisión';}}
if(b.polygon!==undefined&&b.geometry_parts===undefined)delete next.geometry_parts;
if(b.polygon!==undefined||b.geometry_parts!==undefined)next.has_polygon=!!(next.polygon||next.geometry_parts?.length);
if(next.polygon){validatePolygon(next.polygon,doc.width,doc.height);if(b.polygon){for(const other of state.rooms){if(other.id===id||other.document_id!==r.document_id||!other.polygon)continue;let crossing=false;for(let i=0;i<next.polygon.length&&!crossing;i++)for(let j=0;j<other.polygon.length;j++)if(intersects(next.polygon[i],next.polygon[(i+1)%next.polygon.length],other.polygon[j],other.polygon[(j+1)%other.polygon.length])){crossing=true;break;}if(crossing||inside(other.position,next.polygon))throw Error('El contorno invade otro recinto: '+other.code);}}}
const bb=next.diamond_bbox;if(!(bb===null&&current.diamond_bbox===null)&&(!Array.isArray(bb)||bb.length!==4||!bb.every(Number.isFinite)||!(0<=bb[0]&&bb[0]<bb[2]&&bb[2]<=doc.width&&0<=bb[1]&&bb[1]<bb[3]&&bb[3]<=doc.height)))throw Error('Región del rombo inválida.');if(next.finishes.length!==6||new Set(next.finishes.map(f=>f.field)).size!==6)throw Error('Se requieren los seis campos del rombo.');next.finishes=next.finishes.map(f=>{const m=state.materials.find(m=>m.code===f.code);return {...f,description:m?.description||'Sin descripción documentada',category:m?.category||'Sin identificar',asepsis:m?.asepsis||null};});next.asepsis=deriveAsepsis(next.finishes);if(next.status==='Validado'&&(!(next.polygon||next.geometry_parts?.length)||!b.review_confirmed||next.finishes.some(f=>f.description==='Sin descripción documentada')))throw Error('Validar exige contorno, leyenda y confirmación de revisión.');if(b.polygon){next.geometry_method='Edición manual en navegador';next.geometry_status='Pendiente de revisión';}if(next.status==='Validado')next.geometry_status='Validado';next.version=current.version+1;if(JSON.stringify(bb)!==JSON.stringify(current.diamond_bbox))next.diamond_url=null;const before=clone(current),after=clone(next);delete before.history;delete after.history;next.history=[{at:new Date().toISOString(),responsible:b.responsible,reason:b.reason,before_json:JSON.stringify(before),after_json:JSON.stringify(after)},...(current.history||[])];const updated={...records,[id]:next};await checkpoint(records,'Antes de corregir '+id);write(updated);records=updated;stateCache=null;return clone(next);}
export function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function backup(){downloadBlob(new Blob([JSON.stringify({format:'atlas-hpc-backup-v1',level:nivel.id,created:new Date().toISOString(),corrections:read()},null,2)],{type:'application/json'}),archivo('Atlas_HPC_respaldo.json'));}
export async function restore(file){const x=JSON.parse(await file.text());if(x.format!=='atlas-hpc-backup-v1'||!x.corrections||typeof x.corrections!=='object')throw Error('Respaldo de Atlas inválido');if((x.level||'N-1')!==nivel.id)throw Error('Este respaldo es de otro piso. Cambia a ese piso para restaurarlo.');const state=await initializeStore(),merged={...read()};for(const [id,r] of Object.entries(x.corrections)){const original=baseline.rooms.find(y=>y.id===id);if(!original||r.id!==id||r.document_id!==original.document_id)throw Error('El respaldo contiene un recinto desconocido');if(typeof r.code!=='string'||typeof r.name!=='string'||!Array.isArray(r.finishes)||!Array.isArray(r.history)||!Array.isArray(r.notes)||!Array.isArray(r.asepsis))throw Error('Respaldo incompleto');const d=state.documents.find(d=>d.id===r.document_id);if(r.geometry_parts)validateParts(r.geometry_parts,d.width,d.height);if(r.polygon)validatePolygon(r.polygon,d.width,d.height);r.diamond_url=original.diamond_url;merged[id]=r;}await checkpoint(read(),'Antes de importar respaldo');write(merged);records=merged;stateCache=null;return Object.keys(x.corrections).length;}
let pdfLib=null;const pages=new Map();
async function getPage(doc){if(!pdfLib){pdfLib=await import('./vendor/pdf.mjs');pdfLib.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';}if(!pages.has(doc.id)){pages.set(doc.id,pdfLib.getDocument({url:'/source/'+doc.filename,standardFontDataUrl:'/vendor/standard_fonts/'}).promise);if(pages.size>2){const oldest=pages.keys().next().value;pages.get(oldest).then(pdf=>pdf.destroy());pages.delete(oldest);}}return (await pages.get(doc.id)).getPage(1);}
export async function renderRegion(doc,box,max=1600){const page=await getPage(doc),scale=Math.min(8,max/Math.max(box[2],box[3]));const canvas=document.createElement('canvas');canvas.width=Math.ceil(box[2]*scale);canvas.height=Math.ceil(box[3]*scale);await page.render({canvasContext:canvas.getContext('2d'),viewport:page.getViewport({scale}),transform:[1,0,0,1,-box[0]*scale,-box[1]*scale]}).promise;return canvas.toDataURL('image/png');}
export async function diamondURL(r,docs){if(r.diamond_url)return r.diamond_url;const b=r.diamond_bbox;return renderRegion(docs.find(d=>d.id===r.document_id),[b[0],b[1],b[2]-b[0],b[3]-b[1]],600);}
export async function excel(rows){await loadVendor('xlsx');const headers=['Código','Nombre','Nivel','Sector','Documento','Estado','Geometría','Asepsia','M1','M2','M3','M4','CIE','PAV'];const values=rows.map(r=>[r.code,r.name,r.level,r.sector,r.document_id,r.status,r.geometry_status,r.asepsis.join(', '),...headers.slice(8).map(k=>{const f=r.finishes.find(f=>f.field===k);return f.code+' · '+f.description;})]);const ws=XLSX.utils.aoa_to_sheet([headers,...values]);ws['!cols']=headers.map((_,i)=>({wch:i===1||i>7?45:22}));ws['!autofilter']={ref:ws['!ref']};const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Recintos');XLSX.writeFile(wb,archivo('Atlas_HPC_recintos.xlsx'));}
export async function roomPDF(r,docs){await loadVendor('pdf');const {PDFDocument,StandardFonts,rgb}=PDFLib;const pdf=await PDFDocument.create(),page=pdf.addPage([595,842]),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);const safe=s=>String(s).replace(/[^\x20-\xFF\n]/g,'-');let y=800;function text(s,size=11,b=false){const words=safe(s).split(/\s+/);let line='';for(const word of words){if(font.widthOfTextAtSize(line+' '+word,size)>510){page.drawText(line,{x:40,y,size,font:b?bold:font});y-=size+5;line=word;}else line+=(line?' ':'')+word;}if(line){page.drawText(line,{x:40,y,size,font:b?bold:font});y-=size+8;}}
text('ATLAS HPC | FICHA DE RECINTO',18,true);text(r.code+' · '+r.name,13,true);text('Nivel '+r.level+' / Sector '+r.sector+' / '+r.document_id+' / Página 1',10);text('Estado: '+r.status+' / Geometría: '+r.geometry_status,10);if(r.diamond_url||r.diamond_bbox){const url=await diamondURL(r,docs),bytes=await (await fetch(url)).arrayBuffer(),img=await pdf.embedPng(bytes);page.drawImage(img,{x:40,y:y-135,width:135,height:135});y-=160;}for(const f of r.finishes)text(f.field+' · '+f.code+' · '+f.description,10);text('Superficie escrita: '+r.declared_area+' (sin recalcular).',9);text('Clasificación de asepsia de la terminación; no certifica condición sanitaria del recinto.',9);downloadBlob(new Blob([await pdf.save()],{type:'application/pdf'}),'Ficha_'+r.code.replace(/[^\w.-]/g,'_')+'.pdf');}
export async function planPDF(doc,rows){await loadVendor('pdf');const {PDFDocument,rgb}=PDFLib,bytes=await (await fetch('/source/'+doc.filename)).arrayBuffer(),pdf=await PDFDocument.load(bytes,{ignoreEncryption:false}),page=pdf.getPages()[0];for(const r of rows){if(!r.polygon)continue;const points=r.polygon.map(([x,y])=>[y,doc.width-x]);const ring=pts=>'M '+pts.map(([x,y])=>`${y} ${doc.width-x}`).join(' L ')+' Z';const path=ring(r.polygon)+(r.holes||[]).map(ring).join(' ');page.drawSvgPath(path,{x:0,y:page.getHeight(),color:rgb(0,.65,.65),opacity:.25,borderColor:rgb(0,.4,.4),borderWidth:.5});}downloadBlob(new Blob([await pdf.save()],{type:'application/pdf'}),'Plano_'+doc.code+'_filtrado.pdf');}

export async function downloadRecovery(){const snapshot=await latestCheckpoint();if(!snapshot)throw Error('No hay un punto de recuperación guardado.');downloadBlob(new Blob([JSON.stringify({format:'atlas-hpc-backup-v1',level:nivel.id,created:snapshot.at,corrections:snapshot.corrections},null,2)],{type:'application/json'}),archivo('Atlas_HPC_recuperacion.json'));}
